R = []
R.append((7616762,
("Magdalenas rústicas de manzana y pasas sultanas",
 "Son rápidas y fáciles de preparar y llevan abundante fibra integral, por lo que resultan un dulce nutritivo y sabroso. También son muy divertidas de hacer con los niños.",
 ["1 cucharadita de aceite de colza, para engrasar", "300 g de harina integral", "1 cucharadita colmada de polvo para hornear", "1 cucharadita de canela", "1 plátano", "1 huevo mediano", "50 g de azúcar extrafina", "75 ml de aceite de colza", "1 cucharadita de extracto de vainilla", "1 manzana sin corazón, con piel y finamente picada", "75 g de pasas sultanas"],
 ["Precaliente el horno a 180 °C (gas 4) y engrase ligeramente una bandeja grande para hornear con el aceite de colza.", "En un tazón, mezcle la harina, el polvo para hornear y la canela.", "En otro tazón, triture el plátano con un tenedor, añada el huevo y bata bien. Incorpore el azúcar, el aceite, el extracto de vainilla y 50 ml de agua.", "Incorpore poco a poco los ingredientes secos a la mezcla de plátano y huevo con movimientos envolventes; luego incorpore las pasas sultanas y la manzana.", "Coloque la mezcla en 12 montoncitos pequeños e irregulares sobre la bandeja engrasada y use un tenedor para formar muchas puntitas.", "Hornee de 18 a 22 minutos; luego saque del horno y deje enfriar sobre una rejilla."],
 ["Son mejores cuando aún están tibias, pero se pueden guardar en un recipiente hermético de 2 a 3 días.", "Puede añadir otras especias: pruebe con mezcla de especias molidas, jengibre, nuez moscada o cardamomo en lugar de la canela.", "El plátano permite usar menos azúcar y grasa, y además aporta más nutrientes.", "Congele en bolsas para congelador, envueltas en papel de aluminio o papel encerado, hasta por tres meses."]),
("كعكات الصخور بالتفاح والزبيب السلطاني",
 "هذه الكعكات سريعة وسهلة التحضير وغنية بألياف الحبوب الكاملة، فهي حلوى مغذية ولذيذة. كما أن تحضيرها ممتع جدًا مع الأطفال.",
 ["1 ملعقة صغيرة من زيت اللفت (الكانولا) لدهن الصينية", "300 غرام من دقيق القمح الكامل", "1 ملعقة صغيرة مكدسة من البيكنج باودر", "1 ملعقة صغيرة من القرفة", "1 موزة", "1 بيضة متوسطة", "50 غرام من السكر الناعم", "75 مل من زيت اللفت (الكانولا)", "1 ملعقة صغيرة من خلاصة الفانيليا", "1 تفاحة منزوعة القلب وغير مقشرة ومفرومة ناعمًا", "75 غرام من الزبيب السلطاني"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4) وادهن صينية خبز كبيرة بخفة بزيت اللفت.", "في وعاء، اخلط الدقيق والبيكنج باودر والقرفة معًا.", "في وعاء آخر، اهرس الموزة بالشوكة، وأضف البيضة واخفق جيدًا. أضف السكر والزيت وخلاصة الفانيليا و50 مل من الماء وقلّب.", "أضف المكونات الجافة تدريجيًا إلى خليط الموز والبيض مع التقليب بلطف، ثم أضف الزبيب السلطاني والتفاح.", "ضع الخليط على شكل 12 كومة صغيرة غير منتظمة على الصينية المدهونة، واستخدم الشوكة لعمل الكثير من النتوءات الصغيرة.", "اخبزها من 18 إلى 22 دقيقة، ثم أخرجها من الفرن واتركها تبرد على رف سلكي."],
 ["يفضّل تناولها وهي دافئة، لكن يمكن حفظها في علبة محكمة الإغلاق من 2 إلى 3 أيام.", "يمكنك إضافة بهارات أخرى، جرّب خليط البهارات المطحونة أو الزنجبيل أو جوزة الطيب أو الهيل بدلًا من القرفة.", "إضافة الموز تعني استخدام كمية أقل من السكر والدهون مع زيادة العناصر الغذائية.", "جمّدها في أكياس التجميد ملفوفة بورق الألمنيوم أو ورق الزبدة لمدة تصل إلى ثلاثة أشهر."])))
R.append((7618221,
("Pan de ajo",
 "Relleno de cebolla caramelizada, ajo y perejil, y con aceite de oliva en lugar de mantequilla, este pan de ajo es una versión más baja en grasa de la receta clásica.",
 ["1 cucharadita de aceite de colza", "3 cebollas medianas, en rodajas finas", "De 6 a 10 dientes de ajo, machacados", "25 g de perejil, picado", "un molido de pimienta negra", "1 cucharada de aceite de oliva", "1 baguette (aprox. 300 g)", "50 g de mozzarella semidescremada, rallada"],
 ["Precaliente el horno a 180 °C (gas 4). Ponga el aceite en una cacerola a fuego bajo, añada las cebollas y cocínelas suavemente durante 25 minutos, revolviendo con frecuencia, hasta que empiecen a caramelizarse, se doren y se ablanden. Si empiezan a pegarse, añada una cucharadita de agua.", "Mientras tanto, mezcle el ajo machacado, el perejil picado, la pimienta y el aceite de oliva, y reserve.", "Corte la baguette en rodajas de 2 cm de grosor, cortando solo unos tres cuartos del grosor del pan para que se mantenga unido.", "Mezcle las cebollas con la mezcla de ajo y perejil. Coloque una cucharada entre cada rodaja de pan, repartiéndola de manera uniforme.", "Envuelva el pan por completo en papel de aluminio y hornee de 10 a 12 minutos. Abra el papel, cubra con el queso mozzarella y hornee 5 minutos más antes de servir."],
 ["Al caramelizarse, las cebollas se reducen a cerca de un tercio de su cantidad cruda. Es importante cocinarlas muy despacio y revolver con frecuencia con una cuchara de madera.", "Use una baguette integral para aumentar el contenido de fibra.", "Instrucciones para congelar: Se puede congelar listo para cocinar o ya cocido. Corte en rodajas y luego envuelva en papel de aluminio para congelar. Después puede descongelar las rebanadas según las necesite."]),
("خبز الثوم",
 "محشو بالبصل المكرمل والثوم والبقدونس، وبزيت الزيتون بدلًا من الزبدة، وهذا الخبز بالثوم نسخة أقل دهونًا من الوصفة الكلاسيكية.",
 ["1 ملعقة صغيرة من زيت اللفت (الكانولا)", "3 بصلات متوسطة، مقطعة شرائح رفيعة", "من 6 إلى 10 فصوص ثوم، مهروسة", "25 غرامًا من البقدونس، مفرومًا", "رشة فلفل أسود مطحون", "1 ملعقة كبيرة من زيت الزيتون", "1 رغيف باغيت (حوالي 300 غرام)", "50 غرامًا من جبن الموزاريلا قليل الدسم، مبشورًا"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4). ضع الزيت في قدر على نار هادئة، وأضف البصل واطهه برفق لمدة 25 دقيقة مع التقليب بانتظام حتى يبدأ بالتكرمل ويصبح بنيًا وطريًا. إذا بدأ يلتصق، أضف ملعقة صغيرة من الماء.", "في الأثناء، اخلط الثوم المهروس والبقدونس المفروم والفلفل وزيت الزيتون معًا وضعه جانبًا.", "قطّع الباغيت إلى شرائح بسمك 2 سم، مع القطع بنحو ثلاثة أرباع سمك الرغيف فقط ليبقى متماسكًا.", "قلّب البصل مع خليط الثوم والبقدونس. ضع ملعقة من الخليط بين كل شريحتين من الخبز، مع توزيعه بالتساوي بين الشرائح.", "لفّ الخبز بالكامل بورق الألمنيوم واخبزه من 10 إلى 12 دقيقة. افتح ورق الألمنيوم، وضع جبن الموزاريلا فوقه، واخبزه 5 دقائق أخرى قبل التقديم."],
 ["عند تكرمل البصل ينكمش إلى نحو ثلث كميته النيئة. من المهم طهيه ببطء شديد والتقليب بانتظام بملعقة خشبية.", "استخدم باغيت من القمح الكامل لزيادة محتوى الألياف.", "تعليمات التجميد: يمكن تجميده جاهزًا للطهي أو بعد الطهي. قطّعه إلى شرائح ثم لفّه بورق الألمنيوم للتجميد. يمكنك بعد ذلك إذابة التجميد عن الشرائح حسب الحاجة."])))
R.append((7619702,
("Trucha con salsa de cítricos y albahaca",
 "Este plato de pescado es excelente servido con papas nuevas y abundantes verduras o ensalada.",
 ["2 filetes de trucha sin espinas ni piel (de aprox. 100 g cada uno)", "ralladura y jugo de 1 naranja", "2 cucharadas de albahaca, desgarrada", "2 cucharadas de crème fraîche semidescremada", "pimienta negra recién molida"],
 ["Coloque los filetes de trucha en una sartén antiadherente.", "Vierta encima la ralladura y el jugo de naranja, tape y cocine a fuego lento de 5 a 6 minutos, hasta que la trucha esté cocida.", "Incorpore suavemente la albahaca y la crème fraîche y caliente bien. Sazone al gusto."],
 ["Muchos supermercados también venden rodajas gruesas de truchas grandes en lugar de filetes de los peces más pequeños tradicionales. Estas necesitan un poco más de tiempo para cocinarse (de 2 a 3 minutos más, según el tamaño).", "Puede usar eneldo o perejil en lugar de albahaca."]),
("سمك السلمون المرقط بصلصة الحمضيات والريحان",
 "هذا الطبق من السمك ممتاز عند تقديمه مع البطاطس الجديدة والكثير من الخضار أو السلطة.",
 ["2 فيليه سمك سلمون مرقط بدون عظام ولا جلد (وزن كل منهما حوالي 100 غرام)", "قشر وعصير 1 برتقالة مبشورة", "2 ملعقة كبيرة من الريحان، ممزقة", "2 ملعقة كبيرة من الكريمة الحامضة (كريم فريش) قليلة الدسم", "فلفل أسود مطحون طازجًا"],
 ["ضع شرائح السلمون المرقط في مقلاة غير لاصقة.", "اسكب فوقها قشر البرتقال المبشور وعصيره، وغطِّ المقلاة واتركها تغلي على نار هادئة من 5 إلى 6 دقائق حتى ينضج السمك.", "أضف الريحان والكريمة الحامضة برفق وسخّن جيدًا. تبّل حسب الرغبة."],
 ["تبيع كثير من المتاجر الكبرى أيضًا شرائح سميكة من سمك السلمون المرقط الكبير بدلًا من الفيليه المأخوذ من الأسماك الأصغر التقليدية. وتحتاج هذه إلى وقت أطول قليلًا لتنضج (من 2 إلى 3 دقائق إضافية حسب الحجم).", "يمكنك استخدام الشبت أو البقدونس بدلًا من الريحان."])))
R.append((7619710,
("Gratinado de coles de Bruselas",
 "Las coles de Bruselas se hornean en una salsa de queso ligera y se cubren con queso parmesano.",
 ["1 cucharadita de aceite de oliva", "1 cebolla, picada", "1 cucharada de harina común", "una buena pizca de pimienta blanca", "1 cucharadita de mostaza en grano", "300 ml de leche descremada", "30 g de queso Cheddar maduro reducido en grasa", "20 g de queso parmesano", "300 g de coles de Bruselas", "1 cucharada de pan rallado integral"],
 ["Precaliente el horno a 180 °C (gas 4). Caliente el aceite de oliva en una sartén, añada la cebolla y cocine 4 minutos hasta que se ablande, sin dorarla.", "Añada la harina común para cubrir la cebolla, e incorpore una buena pizca de pimienta blanca y la mostaza en grano. Agregue la leche poco a poco, revolviendo, hasta que espese.", "Añada la mitad del queso Cheddar y la mitad del parmesano, revolviendo de 2 a 3 minutos hasta que se derritan. Mientras tanto, hierva las coles en agua hirviendo de 7 a 8 minutos.", "Escurra, coloque en un molde apto para horno, vierta la salsa encima y cubra con el pan rallado integral y el resto del Cheddar y del parmesano. Hornee de 12 a 15 minutos, hasta que la parte superior esté dorada."],
 ["Para más sabor, añada de 2 a 3 dientes de ajo machacados o 1 cucharada de hierbas frescas picadas, como cilantro o cebollín.", "Añada 150 g de champiñones pequeños o un puerro picado para aumentar la cantidad de verduras de este plato.", "Para darle un toque festivo, añada 150 g de castañas cocidas envasadas al vacío.", "Instrucciones para congelar: Descongele en el refrigerador o en el microondas y luego recaliente hasta que esté muy caliente por completo."]),
("غراتان براعم بروكسل",
 "تُخبز براعم بروكسل في صلصة جبن خفيفة وتُغطّى بجبن البارميزان.",
 ["1 ملعقة صغيرة من زيت الزيتون", "1 بصلة، مفرومة", "1 ملعقة كبيرة من الدقيق العادي", "رشة كبيرة من الفلفل الأبيض", "1 ملعقة صغيرة من الخردل بالحبوب الكاملة", "300 مل من الحليب منزوع الدسم", "30 غرامًا من جبن الشيدر الناضج قليل الدسم", "20 غرامًا من جبن البارميزان", "300 غرام من براعم بروكسل", "1 ملعقة كبيرة من فتات خبز القمح الكامل"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4). سخّن زيت الزيتون في مقلاة، وأضف البصل واطهه 4 دقائق حتى يلين دون أن يحمرّ.", "أضف الدقيق العادي ليغطي البصل، ثم أضف رشة كبيرة من الفلفل الأبيض والخردل بالحبوب الكاملة وقلّب. أضف الحليب ببطء مع التحريك حتى يتكاثف.", "أضف نصف كمية الشيدر ونصف كمية البارميزان وحرّك من 2 إلى 3 دقائق حتى يذوب. في الأثناء، اسلق براعم بروكسل في ماء يغلي من 7 إلى 8 دقائق.", "صفِّها وضعها في طبق يتحمل حرارة الفرن، واسكب الصلصة فوقها، وغطِّها بفتات خبز القمح الكامل وما تبقى من الشيدر والبارميزان. اخبزها من 12 إلى 15 دقيقة حتى يصبح وجهها ذهبي اللون."],
 ["لمزيد من النكهة، أضف من 2 إلى 3 فصوص ثوم مهروسة أو 1 ملعقة كبيرة من الأعشاب الطازجة المفرومة، مثل الكزبرة الخضراء أو الثوم المعمر (الشيف).", "أضف 150 غرامًا من الفطر الصغير أو كراثًا مفرومًا لزيادة كمية الخضار في هذا الطبق.", "لإضفاء أجواء احتفالية، أضف 150 غرامًا من الكستناء المطبوخ المعبأ بالتفريغ.", "تعليمات التجميد: اترك المجمّد يذوب في الثلاجة أو في المايكرويف ثم أعد التسخين حتى يسخن تمامًا من الداخل."])))
R.append((7619989,
("Hamburguesas marroquíes de cordero y garbanzos",
 "Deliciosas hamburguesas con influencia del norte de África. Puede cocinarlas en la parrilla, al grill o en una plancha acanalada.",
 ["1 rebanada de pan integral", "1 huevo, batido", "1 lata de 400 g de garbanzos, escurridos", "450 g de carne molida magra de cordero", "1 cebolla, rallada", "1 cucharadita colmada de menta seca", "2 cucharaditas de comino", "de 4 a 6 dientes de ajo, machacados", "1 cucharadita de hojuelas de chile", "8 panes integrales (de 60 g cada uno), partidos por la mitad", "100 g de lechuga", "4 tomates, en rodajas", "1 cebolla morada, en rodajas"],
 ["Desmenuce el pan y añádalo al huevo batido; reserve, pero mezcle de vez en cuando hasta que el pan haya absorbido todo el huevo.", "Mientras tanto, en un tazón grande triture bien la mitad de los garbanzos, luego triture grueso la otra mitad y mezcle todo.", "Añada el cordero, la cebolla, la menta, el comino y las hojuelas de chile y mezcle; luego añada el huevo con el pan y mezcle bien. Lo mejor es hacerlo con las manos, apretando todo junto.", "Forme 8 hamburguesas (de aprox. 8 cm de diámetro y 2½ cm de grosor), colóquelas en un plato o bandeja, cubra con envoltura plástica y refrigere por al menos 20 minutos; una o dos horas es mejor.", "Coloque con cuidado las hamburguesas en la parrilla, en la plancha acanalada o bajo el grill y cocine de 5 a 7 minutos por cada lado. Una vez que las coloque en la plancha o la parrilla, no las mueva ni las voltee hasta que hayan formado una costra (de 4 a 5 minutos). Cuando estén cocidas, póngalas en un plato y cubra con papel de aluminio.", "Tueste los panes si lo desea y arme sus hamburguesas con la lechuga, el tomate y la cebolla."],
 ["Queda bien con carne molida de res o, para una versión más baja en grasa, con carne molida de pavo.", "Pruébelas con pan pita en lugar de panes redondos y rocíe con tzatziki.", "Instrucciones para congelar: Congele en porciones envueltas individualmente, con papel encerado entre cada hamburguesa."]),
("برجر مغربي باللحم الضأن والحمص",
 "برجر لذيذ بنكهة شمال أفريقية. يمكنك شيّه على الفحم أو في الشواية أو طهيه على مقلاة مضلعة.",
 ["1 شريحة خبز قمح كامل", "1 بيضة، مخفوقة", "1 علبة حمص 400 غرام، مصفّاة", "450 غرامًا من لحم الضأن المفروم الخالي من الدهن", "1 بصلة، مبشورة", "1 ملعقة صغيرة مكدسة من النعناع المجفف", "2 ملعقة صغيرة من الكمون", "من 4 إلى 6 فصوص ثوم، مهروسة", "1 ملعقة صغيرة من رقائق الفلفل الحار", "8 أرغفة صغيرة من القمح الكامل (60 غرامًا لكل منها)، مشقوقة", "100 غرام من الخس", "4 حبات طماطم، مقطعة شرائح", "1 بصلة حمراء، مقطعة شرائح"],
 ["فتّت الخبز وأضفه إلى البيض المخفوق، واتركه جانبًا مع التقليب من وقت لآخر حتى يمتص الخبز كل البيض.", "في الأثناء، في وعاء كبير اهرس نصف كمية الحمص جيدًا ثم اهرس النصف الآخر هرسًا خشنًا وقلّبهما معًا.", "أضف لحم الضأن والبصل والنعناع والكمون ورقائق الفلفل الحار واخلط، ثم أضف خليط البيض والخبز واخلط جيدًا. أفضل طريقة هي استخدام اليدين لعجن كل شيء معًا.", "شكّل الخليط إلى 8 أقراص برجر (بقطر حوالي 8 سم وسمك 2½ سم) وضعها على طبق أو صينية، وغطِّها بغلاف بلاستيكي وضعها في الثلاجة لمدة 20 دقيقة على الأقل، وساعة أو ساعتان أفضل.", "ضع أقراص البرجر بعناية على الشواية أو المقلاة المضلعة أو تحت الشواية الكهربائية واطهها من 5 إلى 7 دقائق على كل جانب. بعد وضعها على المقلاة المضلعة أو الشواية لا تحرّكها ولا تقلبها حتى تتكون عليها قشرة (من 4 إلى 5 دقائق). وبعد نضجها ضعها على طبق وغطِّها بورق الألمنيوم.", "حمّص الأرغفة إن رغبت، ثم جهّز البرجر بالخس والطماطم والبصل."],
 ["تناسب هذه الوصفة لحم البقر المفروم، ولنسخة أقل دهونًا استخدم لحم الديك الرومي المفروم.", "جرّبها مع خبز البيتا بدلًا من الأرغفة الصغيرة ورشّ فوقها التزتزيكي (صلصة الزبادي والخيار).", "تعليمات التجميد: جمّد في حصص ملفوفة بشكل منفصل مع وضع ورق الزبدة بين كل قرص برجر."])))
R.append((7621440,
("Nuggets de pollo",
 "Una alternativa a los nuggets del supermercado que encantará a los niños.",
 ["1 cucharadita de aceite de girasol", "1 huevo, batido con una buena pizca de pimienta", "1 cucharada colmada de harina común", "50 g de pan rallado (aprox. 2 rebanadas de pan, desmenuzadas)", "200 g de pechuga de pollo sin hueso y sin piel"],
 ["Precaliente el horno a 190 °C (gas 5). Engrase ligeramente una bandeja para hornear y ponga el huevo batido en un tazón poco profundo. Ponga la harina en un plato llano y el pan rallado en otro plato llano.", "Corte el pollo en trozos del tamaño de un bocado (aprox. 12 a 14) y colóquelos en el plato con la harina; luego mezcle para que cada trozo quede cubierto, separando los trozos para que no se toquen entre sí.", "Lávese y séquese las manos, tome un trozo de pollo, sacuda el exceso de harina, páselo por el huevo y colóquelo sobre el pan rallado. Espolvoree más pan rallado encima para cubrir por completo el pollo y colóquelo en la bandeja para hornear. Repita hasta que todos los nuggets estén cubiertos.", "Hornee de 12 a 15 minutos, hasta que el exterior esté crujiente y ligeramente dorado."],
 ["También puede usar aceite de colza.", "Añada unas hojuelas de chile a la harina para darle un toque picante.", "Instrucciones para congelar: Cocine, enfríe de inmediato y congele sobre una bandeja para hornear. Una vez congelados, colóquelos con cuidado en bolsas por porciones para usarlos. Recaliente muy bien hasta que estén muy calientes."]),
("قطع الدجاج المقرمشة (ناجتس)",
 "بديل لناجتس المتاجر الكبرى سيحبه الأطفال.",
 ["1 ملعقة صغيرة من زيت دوار الشمس", "1 بيضة، مخفوقة مع رشة كبيرة من الفلفل", "1 ملعقة كبيرة مكدسة من الدقيق العادي", "50 غرامًا من فتات الخبز (حوالي شريحتين من الخبز المفتت)", "200 غرام من صدر دجاج بدون عظم ولا جلد"],
 ["سخّن الفرن مسبقًا إلى 190° مئوية (علامة الغاز 5). ادهن صينية خبز بقليل من الزيت وضع البيض المخفوق في وعاء واسع قليل العمق. ضع الدقيق في طبق مسطح وفتات الخبز في طبق مسطح آخر.", "قطّع الدجاج إلى قطع بحجم لقمة (حوالي 12 إلى 14 قطعة) وضعها في طبق الدقيق ثم قلّبها لتتغطى كل قطعة، وافصل القطع عن بعضها بحيث لا تتلامس.", "اغسل يديك وجففهما، ثم التقط قطعة دجاج، وانفض الدقيق الزائد، واغمسها في البيض وضعها على فتات الخبز. رشّ المزيد من الفتات فوقها لتغطية الدجاج بالكامل وضعها على صينية الخبز. كرر العملية حتى تغطى جميع القطع.", "اخبزها من 12 إلى 15 دقيقة حتى يصبح الخارج مقرمشًا ومائلًا للاحمرار الخفيف."],
 ["يمكنك أيضًا استخدام زيت اللفت (الكانولا).", "أضف بعض رقائق الفلفل الحار إلى الدقيق لإضفاء لمسة حارة.", "تعليمات التجميد: اطهها ثم برّدها فورًا وجمّدها على صينية خبز. وبعد تجمدها ضعها بعناية في أكياس حسب الحصص للاستخدام. أعد تسخينها جيدًا حتى تصبح ساخنة تمامًا."])))
R.append((7624456,
("Vieiras con mantequilla de lima y chile",
 "Deliciosas para recibir invitados: sírvalas como entrada o como una comida ligera con pan crujiente.",
 ["15 g de mantequilla, blanda", "1 cucharada de aceite de oliva", "de medio a 1 chile rojo, finamente picado", "ralladura y jugo de 1 lima", "pimienta negra recién molida", "12 vieiras, limpias", "hojas de arúgula, para servir"],
 ["En un tazón pequeño, bata juntos la mantequilla, el aceite, el chile y la ralladura y el jugo de la lima. Sazone bien.", "Caliente una sartén antiadherente, añada la mezcla de mantequilla y caliente hasta que burbujee. Añada las vieiras y fría aproximadamente 1 minuto por cada lado.", "Retire de la sartén, sirva con un poco de arúgula y rocíe con los jugos de la sartén."],
 ["También puede añadir a la mantequilla 2 cm de jengibre fresco finamente picado y 2 dientes de ajo machacados.", "Esta receta también funciona con camarones o cubos de salmón fresco."]),
("إسكالوب (محار الأسقلوب) بزبدة الليمون الأخضر والفلفل الحار",
 "لذيذ للضيافة، قدّمه كمقبلات أو كوجبة خفيفة مع خبز مقرمش.",
 ["15 غرامًا من الزبدة، طرية", "1 ملعقة كبيرة من زيت الزيتون", "من نصف إلى 1 حبة فلفل حار أحمر، مفرومة ناعمًا", "قشر وعصير 1 ليمونة خضراء مبشورة", "فلفل أسود مطحون طازجًا", "12 حبة إسكالوب، منظّفة", "أوراق جرجير، للتقديم"],
 ["في وعاء صغير، اخفق الزبدة والزيت والفلفل الحار وقشر الليمون الأخضر وعصيره معًا. تبّل جيدًا.", "سخّن مقلاة غير لاصقة، وأضف خليط الزبدة وسخّنه حتى يغلي ويفور. أضف الإسكالوب وقلّه نحو دقيقة واحدة على كل جانب.", "أخرجه من المقلاة وقدّمه مع قليل من الجرجير وصبّ فوقه عصارة المقلاة."],
 ["يمكنك أيضًا إضافة 2 سم من الزنجبيل الطازج المفروم ناعمًا و2 فص ثوم مهروس إلى الزبدة.", "تصلح هذه الوصفة أيضًا مع الروبيان أو مكعبات السلمون الطازج."])))
R.append((7627305,
("Albóndigas mexicanas de pavo",
 "Acompáñelas con arroz integral y verduras al vapor para una comida de entre semana abundante y satisfactoria.",
 ["500 g de carne molida de pechuga de pavo", "50 g de pan, procesado hasta obtener pan rallado grueso", "1 cucharada de chile en polvo suave", "1 cucharadita de pimentón ahumado", "½ cucharadita de canela molida", "½ cucharadita de comino molido", "½ cucharadita de ajo en polvo", "½ cucharadita de orégano seco", "Aceite en aerosol para cocinar, bajo en calorías", "1 cebolla, en rodajas finas", "2 latas de 400 g de tomates picados", "1 lata de 400 g de frijoles rojos en agua, enjuagados y escurridos", "Hojas de cilantro fresco, para servir", "2 cucharadas de yogur griego natural sin grasa (0 %), para servir"],
 ["Combine la carne, el pan rallado y la mitad de las especias y hierbas secas en un tazón. Forme 20 bolitas con la mezcla.", "Rocíe ligeramente una sartén antiadherente con aceite en aerosol. Cocine las albóndigas a fuego medio, volteándolas de vez en cuando, durante 5 minutos o hasta que se doren por todos lados.", "Aparte las albóndigas y vuelva a rociar la sartén. Añada la cebolla, cocine 5 minutos y luego añada el resto de las especias y hierbas secas, junto con los tomates, los frijoles rojos, 125 ml de agua y las albóndigas. Revuelva y deje que hierva. Reduzca el fuego y cocine a fuego lento, tapado, durante 10 minutos o hasta que las albóndigas estén cocidas.", "Sirva cubierto con el cilantro y el yogur."],
 ["Añada un pimiento rojo picado a las cebollas para aumentar la cantidad de verduras y el sabor de la salsa."]),
("كرات اللحم المكسيكية بالديك الرومي",
 "قدّمها مع الأرز البني والخضار المطهوة على البخار لوجبة مشبعة ومرضية في منتصف الأسبوع.",
 ["500 غرام من لحم صدر الديك الرومي المفروم", "50 غرامًا من الخبز، مطحونًا إلى فتات خشن", "1 ملعقة كبيرة من مسحوق الفلفل الحار الخفيف", "1 ملعقة صغيرة من البابريكا المدخنة", "½ ملعقة صغيرة من القرفة المطحونة", "½ ملعقة صغيرة من الكمون المطحون", "½ ملعقة صغيرة من مسحوق الثوم", "½ ملعقة صغيرة من الأوريغانو المجفف", "بخاخ طهي قليل السعرات", "1 بصلة، مقطعة شرائح رفيعة", "2 علبة طماطم مفرومة 400 غرام", "1 علبة فاصوليا حمراء 400 غرام في الماء، مشطوفة ومصفّاة", "أوراق كزبرة خضراء طازجة، للتقديم", "2 ملعقة كبيرة من الزبادي اليوناني الطبيعي خالي الدسم (0%)، للتقديم"],
 ["اخلط اللحم المفروم وفتات الخبز ونصف كمية التوابل والأعشاب المجففة في وعاء. شكّل الخليط إلى 20 كرة.", "رشّ مقلاة غير لاصقة برذاذ الطهي بخفة. اطه كرات اللحم على نار متوسطة مع تقليبها من حين لآخر لمدة 5 دقائق أو حتى تحمرّ من كل الجوانب.", "ضع كرات اللحم جانبًا ورشّ المقلاة مرة أخرى. أضف البصل واطهه 5 دقائق، ثم أضف باقي التوابل والأعشاب المجففة مع الطماطم والفاصوليا الحمراء و125 مل من الماء وكرات اللحم. قلّب ثم اتركه حتى يغلي. خفّف النار واتركه على نار هادئة مغطى لمدة 10 دقائق أو حتى تنضج كرات اللحم.", "قدّمها مع الكزبرة الخضراء والزبادي."],
 ["أضف حبة فلفل رومي أحمر مفرومة إلى البصل لزيادة كمية الخضار ونكهة الصلصة."])))
R.append((7628199,
("Tartiflette (salteado para el desayuno)",
 "Este contundente plato de papas proviene de los Alpes franceses y es ideal para un desayuno abundante de fin de semana.",
 ["150 g de papas pequeñas", "2 cucharaditas de aceite de colza", "150 g de champiñones pequeños, en cuartos", "6 cebollas verdes, limpias y cortadas en trozos de 1 cm", "1 cucharadita colmada de harina común", "150 ml de leche descremada", "30 g de queso Cheddar maduro, rallado", "pimienta negra, para sazonar"],
 ["Hierva las papas enteras con su piel de 15 a 25 minutos, según el tamaño. Escurra y luego corte en una mezcla de mitades y cuartos.", "Caliente el aceite de colza en una sartén grande y añada las papas. Cocine, volteando con frecuencia, durante 3 minutos.", "Añada los champiñones a la sartén con las papas y cocine, revolviendo, otros 3 minutos; luego añada las cebollas verdes y cocine, revolviendo, 2 minutos más.", "Espolvoree la harina sobre todo y revuelva para mezclar bien. Luego vierta poco a poco la leche, revolviendo constantemente, de 2 a 3 minutos.", "Incorpore el queso, sazone con pimienta y sirva."],
 []),
("تارتيفليت (طبق مقلي للفطور)",
 "هذا الطبق المشبع من البطاطس مصدره جبال الألب الفرنسية، وهو رائع لوجبة فطور دسمة في عطلة نهاية الأسبوع.",
 ["150 غرامًا من البطاطس الصغيرة", "2 ملعقة صغيرة من زيت اللفت (الكانولا)", "150 غرامًا من الفطر الصغير، مقطعًا أرباعًا", "6 حبات بصل أخضر، منظّفة ومقطعة إلى قطع بطول 1 سم", "1 ملعقة صغيرة مكدسة من الدقيق العادي", "150 مل من الحليب منزوع الدسم", "30 غرامًا من جبن الشيدر الناضج، مبشورًا", "فلفل أسود، للتتبيل"],
 ["اسلق حبات البطاطس كاملة بقشرها من 15 إلى 25 دقيقة حسب حجمها. صفّها ثم قطّعها إلى أنصاف وأرباع.", "سخّن زيت اللفت (الكانولا) في مقلاة كبيرة وأضف البطاطس. قلّبها باستمرار لمدة 3 دقائق.", "أضف الفطر إلى المقلاة مع البطاطس واطهه مع التحريك 3 دقائق أخرى، ثم أضف البصل الأخضر واطهه مع التحريك دقيقتين إضافيتين.", "رشّ الدقيق على المكونات وحرّك لخلطها جيدًا. بعد ذلك اسكب الحليب تدريجيًا مع التحريك المستمر من 2 إلى 3 دقائق.", "أضف الجبن وتبّل بالفلفل وقدّم."],
 [])))
R.append((7639641,
("Ensalada arcoíris",
 "Una mezcla de camote con espárragos, zanahoria, habas y chícharos, unida con una salsa cremosa a base de yogur. Se puede servir fría o tibia y es ideal para acompañar carne o pescado a la parrilla.",
 ["2 camotes, pelados y cortados en 3 trozos grandes", "1 zanahoria, pelada y cortada en 3 trozos grandes", "150 g de espárragos en manojo, sin las partes duras de los tallos", "50 g de habas congeladas", "50 g de chícharos congelados", "150 g de cebollas verdes, limpias y finamente picadas", "de 8 a 10 pepinillos cornichon (pepinillos pequeños), finamente picados", "2 cucharadas colmadas de yogur estilo griego sin grasa (0 %)", "1 cucharada de mayonesa ligera", "1 cucharadita colmada de mostaza Dijon", "una buena pizca de pimienta"],
 ["Añada los camotes y las zanahorias a una olla con agua hirviendo y hierva 10 minutos.", "Añada los espárragos y siga hirviendo 5 minutos.", "Compruebe que los espárragos estén cocidos y sáquelos de la olla; revise también las zanahorias y los camotes, y sáquelos o siga cocinándolos un par de minutos más si todavía no están tiernos.", "Cuando los camotes y las zanahorias estén cocidos, apague el fuego y añada las habas y los chícharos a la olla. Esto los descongelará y evitará que las demás verduras se cocinen en exceso.", "Escurra las verduras, deje enfriar y luego corte en cubos el camote y la zanahoria, y corte los espárragos en rodajas de ½ cm.", "Prepare el aderezo mezclando todos los ingredientes.", "Incorpore con cuidado el camote, la zanahoria, los espárragos, las habas y los chícharos al aderezo y sirva."],
 ["Puede añadir a esta ensalada casi cualquier verdura cocida, incluidos ejotes, apio y manzana.", "Si desea una ensalada arcoíris tibia, simplemente corte en cubos y mezcle las verduras en cuanto estén cocidas y sirva de inmediato."]),
("سلطة قوس قزح",
 "خليط من البطاطا الحلوة مع الهليون والجزر والفول والبازلاء، مغطى بصلصة كريمية أساسها الزبادي. يمكن تقديمها باردة أو دافئة، وهي مثالية مع اللحم أو السمك المشوي.",
 ["2 حبة بطاطا حلوة، مقشرة ومقطعة إلى 3 قطع كبيرة", "1 جزرة، مقشرة ومقطعة إلى 3 قطع كبيرة", "150 غرامًا من حزمة الهليون، مع إزالة السيقان القاسية", "50 غرامًا من الفول المجمد", "50 غرامًا من البازلاء المجمدة", "150 غرامًا من البصل الأخضر، منظّفًا ومفرومًا ناعمًا", "من 8 إلى 10 حبات من مخلل الخيار الصغير (كورنيشون)، مفرومة ناعمًا", "2 ملعقة كبيرة مكدسة من الزبادي اليوناني خالي الدسم (0%)", "1 ملعقة كبيرة من المايونيز الخفيف", "1 ملعقة صغيرة مكدسة من خردل ديجون", "رشة كبيرة من الفلفل"],
 ["ضع البطاطا الحلوة والجزر في قدر من الماء المغلي واتركهما يغليان 10 دقائق.", "أضف الهليون واستمر في الغليان 5 دقائق.", "تأكد من نضج الهليون وأخرجه من القدر، وافحص الجزر والبطاطا الحلوة أيضًا، فأخرجهما أو واصل طهيهما دقيقتين إضافيتين إذا لم تكن طرية بعد.", "عند نضج البطاطا الحلوة والجزر، أطفئ النار وأضف الفول والبازلاء إلى القدر. سيؤدي ذلك إلى إذابة تجمّدها ويمنع الخضار الأخرى من الإفراط في النضج.", "صفِّ الخضار واتركها تبرد، ثم قطّع البطاطا الحلوة والجزر إلى مكعبات وقطّع الهليون إلى حلقات بسمك ½ سم.", "حضّر التتبيلة بخلط جميع المكونات معًا.", "قلّب البطاطا الحلوة والجزر والهليون والفول والبازلاء مع التتبيلة بلطف وقدّم."],
 ["يمكنك إضافة أي خضار مطبوخة تقريبًا إلى هذه السلطة، بما في ذلك الفاصوليا الخضراء والكرفس والتفاح.", "إذا أردت سلطة قوس قزح دافئة، فقطّع الخضار إلى مكعبات واخلطها فور نضجها وقدّمها على الفور."])))
R.append((7641472,
("Berenjena rellena al horno",
 "Las cáscaras de berenjena asadas y rellenas son la manera perfecta de disfrutar de los fabulosos sabores del Mediterráneo este verano. Esta receta fue seleccionada en colaboración con Slimming World.",
 ["4 berenjenas", "Aceite en aerosol para cocinar, bajo en calorías", "1 cebolla grande, finamente picada", "4 dientes de ajo, finamente picados", "300 g de tomates cherry rojos y amarillos, cortados por la mitad o en cuartos", "30 g de hojas de albahaca fresca, finamente picadas, y además hojas desgarradas para servir", "1 chile rojo, finamente picado", "1 cucharadita de hierbas italianas secas", "280 g de mozzarella reducida en grasa, picada en trozos grandes", "Ensalada de hojas mixtas, para servir"],
 ["Precaliente el horno a 200 °C (con ventilador, 180 °C; gas 6).", "Corte las berenjenas por la mitad a lo largo y, con un cuchillo pequeño, haga un corte de 1 cm de grosor como borde dentro de cada mitad. Saque y reserve la pulpa del interior de los bordes, de modo que le queden 8 cáscaras de berenjena de 1 cm de grosor. Colóquelas en una bandeja antiadherente para hornear, con el lado cortado hacia arriba, rocíe con un par de pulverizaciones de aceite en aerosol bajo en calorías y sazone ligeramente con pimienta y hierbas secas mixtas, si lo desea. Cubra con papel de aluminio y hornee de 15 a 20 minutos.", "Mientras se cocinan, pique finamente la pulpa de la berenjena. Rocíe una sartén antiadherente con unas pulverizaciones de aceite en aerosol bajo en calorías y saltee la berenjena y la cebolla de 10 a 15 minutos, o hasta que se ablanden. Añada el ajo, los tomates, la albahaca picada, el chile y el condimento italiano y saltee de 2 a 3 minutos más. Retire del fuego e incorpore la mitad de la mozzarella.", "Reparta la mezcla entre las cáscaras de berenjena cocidas y esparza encima el resto de la mozzarella. Vuelva a meter al horno durante 20 minutos, o hasta que estén ligeramente doradas, y luego esparza encima la albahaca desgarrada. Sirva 2 mitades de berenjena por persona con la ensalada."],
 ["Obtenga más información sobre nuestra colaboración con Slimming World."]),
("باذنجان محشو مخبوز",
 "قشور الباذنجان المشوية والمحشوة هي الطريقة المثالية للاستمتاع بنكهات البحر المتوسط الرائعة هذا الصيف! تم اختيار هذه الوصفة بالشراكة مع Slimming World.",
 ["4 حبات باذنجان", "بخاخ طهي منخفض السعرات", "1 بصلة كبيرة، مفرومة ناعمًا", "4 فصوص ثوم، مفرومة ناعمًا", "300 غرام من الطماطم الكرزية الحمراء والصفراء، مقطعة إلى أنصاف أو أرباع", "30 غرامًا من أوراق الريحان الطازجة، مفرومة ناعمًا، بالإضافة إلى أوراق ممزقة للتقديم", "1 حبة فلفل حار أحمر، مفرومة ناعمًا", "1 ملعقة صغيرة من الأعشاب الإيطالية المجففة", "280 غرامًا من جبن الموزاريلا قليل الدسم، مقطعًا قطعًا كبيرة", "سلطة أوراق مشكلة، للتقديم"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (180° مئوية مع المروحة، علامة الغاز 6).", "اقطع الباذنجان إلى نصفين بالطول، واستخدم سكينًا صغيرة لعمل حافة بسمك 1 سم داخل كل نصف. أخرج لب الباذنجان من داخل الحواف واحتفظ به جانبًا، بحيث تحصل على 8 قشور باذنجان بسمك 1 سم. ضعها على صينية خبز غير لاصقة والجهة المقطوعة لأعلى، ثم رشّها بضغطتين من بخاخ الطهي المنخفض السعرات وتبّلها بخفة بالفلفل والأعشاب المجففة المشكلة إن رغبت. غطِّها بورق الألمنيوم واخبزها من 15 إلى 20 دقيقة.", "أثناء نضجها، افرم لب الباذنجان ناعمًا. رشّ مقلاة غير لاصقة بضغطات قليلة من بخاخ الطهي المنخفض السعرات وقلّب الباذنجان والبصل من 10 إلى 15 دقيقة أو حتى يلينا. أضف الثوم والطماطم والريحان المفروم والفلفل الحار والتوابل الإيطالية وقلّب من 2 إلى 3 دقائق إضافية. ارفعه عن النار وأضف نصف كمية الموزاريلا وقلّب.", "وزّع الخليط على قشور الباذنجان المطبوخة، ثم انثر فوقها بقية الموزاريلا. أعدها إلى الفرن لمدة 20 دقيقة أو حتى تحمرّ قليلًا، ثم انثر فوقها الريحان الممزق. قدّم نصفين من الباذنجان لكل شخص مع السلطة."],
 ["اعرف المزيد عن شراكتنا مع Slimming World."])))
R.append((7642926,
("Sopa ligera y esponjosa de berro",
 "Ideal para el almuerzo en un día de verano, esta sopa se puede servir caliente o fría. Si hace mucho calor, sírvala con un par de cubos de hielo.",
 ["1 cucharadita de aceite de colza", "1 cebolla grande, picada", "250 g de papas, peladas y cortadas en cubos pequeños", "1.2 L de caldo de verduras", "300 g de berro", "300 ml de yogur natural bajo en grasa; reserve 2 cucharadas para servir", "pimienta negra recién molida"],
 ["Caliente el aceite en una cacerola, añada la cebolla y la papa y fría de 2 a 3 minutos. Añada el caldo a la cacerola, deje que hierva y cocine a fuego lento de 15 a 20 minutos, hasta que la papa esté tierna.", "Retire la cacerola del fuego, añada el berro y licue con una licuadora de inmersión o un procesador de alimentos hasta que quede suave.", "Cuando esté completamente licuada, añada el yogur, sazone bien y caliente suavemente, sin que hierva; luego licue 1 minuto más.", "Sirva cubierta con una espiral de yogur y una pizca de pimienta negra."],
 ["Un cucharón de esta sopa sirve como una excelente salsa para acompañar pescado a la parrilla o platos vegetarianos como brochetas de tofu con arroz.", "Instrucciones para congelar: Se puede congelar en recipientes pequeños para porciones individuales. Descongele en el microondas, lentamente, hasta que esté muy caliente."]),
("شوربة الجرجير المائي الخفيفة والهشة",
 "مثالية لوجبة الغداء في يوم صيفي، ويمكن تقديم هذه الشوربة ساخنة أو باردة. وإذا كان اليوم شديد الحرارة، فقدّمها مع مكعبين من الثلج.",
 ["1 ملعقة صغيرة من زيت اللفت (الكانولا)", "1 بصلة كبيرة، مفرومة", "250 غرامًا من البطاطس، مقشرة ومقطعة مكعبات صغيرة", "1.2 لتر من مرق الخضار", "300 غرام من الجرجير المائي (الرشاد)", "300 مل من الزبادي الطبيعي قليل الدسم، مع تخصيص 2 ملعقة كبيرة للتقديم", "فلفل أسود مطحون طازجًا"],
 ["سخّن الزيت في قدر، وأضف البصل والبطاطس وقلّبهما من 2 إلى 3 دقائق. أضف المرق إلى القدر واتركه حتى يغلي ثم اتركه على نار هادئة من 15 إلى 20 دقيقة حتى تنضج البطاطس.", "ارفع القدر عن النار، وأضف الجرجير المائي وامزج بخلاط يدوي أو معالج طعام حتى يصبح ناعمًا.", "بعد أن يصبح الخليط ناعمًا تمامًا، أضف الزبادي وتبّل جيدًا وسخّنه برفق دون أن يغلي، ثم امزجه دقيقة إضافية.", "قدّمها مع دوّامة من الزبادي ورشة من الفلفل الأسود."],
 ["مغرفة من هذه الشوربة تصلح كصلصة رائعة تُقدَّم مع السمك المشوي أو الأطباق النباتية مثل أسياخ التوفو مع الأرز.", "تعليمات التجميد: يمكن تجميدها في أوعية صغيرة لحصص فردية. أذبها في المايكرويف ببطء حتى تسخن تمامًا."])))
build(1, R)
